begin;
select no_plan();
create function pg_temp.sp_id(n integer) returns uuid language sql immutable as $$select ('aa033000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,instance_id,aud,role,email) select pg_temp.sp_id(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','ai-policy-'||n||'@test.invalid' from generate_series(1,9)n;
insert into public.profiles(id,role,name) select pg_temp.sp_id(n),case n when 1 then 'admin' when 2 then 'staff' when 3 then 'teacher' when 4 then 'assistant' when 5 then 'viewer' else 'staff' end,'policy fixture' from generate_series(1,8)n on conflict(id) do update set role=excluded.role;
update auth.users set deleted_at=clock_timestamp() where id=pg_temp.sp_id(6);
update auth.users set banned_until=clock_timestamp()+interval '1 day' where id=pg_temp.sp_id(7);
delete from public.profiles where id=pg_temp.sp_id(9);
create function pg_temp.sp_set(n integer,rev text,keys jsonb,k integer) returns jsonb language sql as $$select public.ai_agent_space_policy_api_v1('set',jsonb_build_object('userId',pg_temp.sp_id(n),'revision',rev,'spaceKeys',keys,'idempotencyKey',pg_temp.sp_id(k)))$$;
create temp table policy_evidence(k text primary key,v jsonb);
grant all on policy_evidence to authenticated;
select set_config('request.jwt.claim.sub',pg_temp.sp_id(1)::text,true);
set local role authenticated;
insert into policy_evidence values('catalog',public.ai_agent_space_policy_api_v1('catalog','{}'));
select is(jsonb_array_length((select v->'items' from policy_evidence where k='catalog')),7,'admin fixed seven-slot catalog');
select is((select jsonb_agg(x->>'label') from policy_evidence e,jsonb_array_elements(e.v->'items')x where e.k='catalog'),'["경영팀","관리팀","조교팀","영어팀","전체공지","수학팀","과학팀"]'::jsonb,'fixed symbolic labels');
select ok((select bool_and(not (x->>'configured')::boolean and not (x->>'selectable')::boolean and x->>'reason'='space_not_configured' and x->>'revision'='1') from policy_evidence e,jsonb_array_elements(e.v->'items')x where e.k='catalog'),'all runtime slots remain unconfigured');
select is(public.ai_agent_space_policy_api_v1('get',jsonb_build_object('userId',pg_temp.sp_id(2))),jsonb_build_object('userId',pg_temp.sp_id(2),'spaceKeys','[]'::jsonb,'revision','0','updatedAt',null),'absent policy revision0 and empty permissions');
insert into policy_evidence values('first',pg_temp.sp_set(2,'0','["space_2","space_1"]',101));
select is((select v->>'revision' from policy_evidence where k='first'),'1','first CAS0 creates revision1');
select is((select v->'spaceKeys' from policy_evidence where k='first'),'["space_1","space_2"]'::jsonb,'stored policy keys canonical order');
select is(pg_temp.sp_set(2,'0','["space_2","space_1"]',101),(select v from policy_evidence where k='first'),'exact replay returns original DTO');
select throws_ok($q$select pg_temp.sp_set(2,'0','["space_3"]',101)$q$,'23514','ai_agent_idempotency_conflict','changed same-key payload conflict');
select throws_ok($q$select pg_temp.sp_set(2,'0','[]',102)$q$,'55000','ai_agent_stale_version','stale CAS exact55000');
select throws_ok($q$select pg_temp.sp_set(2,'1','["space_8"]',103)$q$,'22023','ai_agent_invalid','unknown slot denied');
select throws_ok($q$select pg_temp.sp_set(2,'1','["space_1","space_1"]',103)$q$,'22023','ai_agent_invalid','duplicates denied');
select throws_ok($q$select pg_temp.sp_set(2,'1','[null]',103)$q$,'22023','ai_agent_invalid','null slot denied');
select throws_ok($q$select pg_temp.sp_set(2,'1','[1]',103)$q$,'22023','ai_agent_invalid','nonstring slot denied');
select throws_ok($q$select pg_temp.sp_set(2,'9223372036854775808','[]',103)$q$,'22023','ai_agent_invalid','bigint overflow denied');
select throws_ok($q$select pg_temp.sp_set(2,'01','[]',103)$q$,'22023','ai_agent_invalid','noncanonical revision denied');
select throws_ok($q$select public.ai_agent_space_policy_api_v1('set',jsonb_build_object('userId',pg_temp.sp_id(2),'spaceKeys','[]'::jsonb,'idempotencyKey',pg_temp.sp_id(103)))$q$,'22023','ai_agent_precondition_required','absent revision precondition');
select throws_ok($q$select public.ai_agent_space_policy_api_v1('set',jsonb_build_object('userId',pg_temp.sp_id(2),'revision','1','spaceKeys','[]'::jsonb,'idempotencyKey',pg_temp.sp_id(103),'actorId',pg_temp.sp_id(1)))$q$,'22023','ai_agent_invalid','caller actor forbidden');
select throws_ok($q$select public.ai_agent_space_policy_api_v1('catalog','{"userId":"x"}')$q$,'22023','ai_agent_invalid','catalog extra fields denied');
select throws_ok($q$select public.ai_agent_space_policy_api_v1('get','{"userId":"x"}')$q$,'22023','ai_agent_invalid','malformed target denied');
select throws_ok($q$select pg_temp.sp_set(1,'0','["space_1"]',103)$q$,'42501','ai_agent_space_forbidden','admin catalog access does not create employee grants');
select throws_ok($q$select pg_temp.sp_set(5,'0','["space_1"]',103)$q$,'42501','ai_agent_space_forbidden','viewer target cannot receive grant');
select throws_ok($q$select pg_temp.sp_set(6,'0','["space_1"]',103)$q$,'42501','ai_agent_space_forbidden','deleted target cannot receive grant');
select throws_ok($q$select pg_temp.sp_set(7,'0','["space_1"]',103)$q$,'42501','ai_agent_space_forbidden','banned target cannot receive grant');
select lives_ok($q$select pg_temp.sp_set(3,'0','["space_3"]',104)$q$,'active teacher can receive policy');
select lives_ok($q$select pg_temp.sp_set(4,'0','["space_4"]',105)$q$,'active assistant can receive policy');
reset role;
select is((select count(*)::integer from dashboard_private.ai_agent_space_policy_events where user_id=pg_temp.sp_id(2)),1,'replay creates no additional audit');
select is((select before_revision::text||':'||after_revision::text from dashboard_private.ai_agent_space_policy_events where user_id=pg_temp.sp_id(2)),'0:1','audit before/after revision');
select ok((select actor_id=pg_temp.sp_id(1) and before_space_keys='{}' and after_space_keys=array['space_1','space_2'] from dashboard_private.ai_agent_space_policy_events where user_id=pg_temp.sp_id(2)),'audit preserves authenticated actor and before/after keys');
-- Synthetic configuration only, rolled back with every fixture in this test.
update dashboard_private.chat_space_configuration set configured=true,public_origin='https://dashboard.test.invalid',resource_name='spaces/POLICY_FIXTURE',revision=2 where space_key in('space_1','space_3');
select set_config('request.jwt.claim.sub',pg_temp.sp_id(2)::text,true);
set local role authenticated;
insert into policy_evidence values('staff',public.ai_agent_space_policy_api_v1('catalog','{}'));
select ok((select (x->>'selectable')::boolean and x->'reason'='null'::jsonb and x->>'revision'='2' from policy_evidence e,jsonb_array_elements(e.v->'items')x where e.k='staff' and x->>'key'='space_1'),'configured permitted slot selectable');
select is((select x->>'reason' from policy_evidence e,jsonb_array_elements(e.v->'items')x where e.k='staff' and x->>'key'='space_3'),'space_not_allowed','configured nonpermitted slot denied');
select is((select x->>'reason' from policy_evidence e,jsonb_array_elements(e.v->'items')x where e.k='staff' and x->>'key'='space_2'),'space_not_configured','saved unconfigured permission remains disabled');
select throws_ok($q$select public.ai_agent_space_policy_api_v1('get',jsonb_build_object('userId',pg_temp.sp_id(2)))$q$,'42501','ai_agent_forbidden','staff cannot get policy');
select throws_ok($q$select pg_temp.sp_set(2,'1','[]',106)$q$,'42501','ai_agent_forbidden','staff cannot set policy');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.sp_id(3)::text,true);
set local role authenticated;
select ok((select (x->>'selectable')::boolean from jsonb_array_elements(public.ai_agent_space_policy_api_v1('catalog','{}')->'items')x where x->>'key'='space_3'),'teacher catalog intersects own permission');
select throws_ok($q$select public.ai_agent_space_policy_api_v1('get',jsonb_build_object('userId',pg_temp.sp_id(3)))$q$,'42501','ai_agent_forbidden','teacher cannot get policy');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.sp_id(4)::text,true);
set local role authenticated;
select throws_ok($q$select public.ai_agent_space_policy_api_v1('catalog','{}')$q$,'42501','ai_agent_forbidden','assistant cannot read AI catalog');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.sp_id(8)::text,true);
set local role authenticated;
select is(jsonb_array_length(public.ai_agent_space_policy_api_v1('catalog','{}')->'items'),7,'allowed staff catalog includes fixed seven slots');
select is((select x->>'reason' from jsonb_array_elements(public.ai_agent_space_policy_api_v1('catalog','{}')->'items')x where x->>'key'='space_3'),'space_not_allowed','staff cannot inherit teacher permission');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.sp_id(4)::text,true);
set local role authenticated;
select throws_ok($q$select pg_temp.sp_set(4,'1','[]',106)$q$,'42501','ai_agent_forbidden','assistant cannot set policy');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.sp_id(1)::text,true);
set local role authenticated;
select ok((select bool_and((x->>'selectable')::boolean) from jsonb_array_elements(public.ai_agent_space_policy_api_v1('catalog','{}')->'items')x where x->>'key' in('space_1','space_3')),'admin configured catalog independent of user policy');
select is(pg_temp.sp_set(2,'1','[]',106)->>'revision','2','explicit revocation advances revision');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.sp_id(2)::text,true);
set local role authenticated;
select is((select x->>'reason' from jsonb_array_elements(public.ai_agent_space_policy_api_v1('catalog','{}')->'items')x where x->>'key'='space_1'),'space_not_allowed','latest revocation removes selection');
reset role;
update public.profiles set role='viewer' where id=pg_temp.sp_id(3);
update auth.users set deleted_at=clock_timestamp() where id=pg_temp.sp_id(4);
select set_config('request.jwt.claim.sub',pg_temp.sp_id(1)::text,true);
set local role authenticated;
select is(pg_temp.sp_set(3,'1','[]',107)->>'revision','2','existing downgraded target may be explicitly revoked');
select is(pg_temp.sp_set(4,'1','[]',108)->>'revision','2','existing deleted target may be explicitly revoked');
select throws_ok($q$select pg_temp.sp_set(3,'0','["space_3"]',104)$q$,'42501','ai_agent_space_forbidden','replay rechecks current target authority');
reset role;
create function pg_temp.sp_denied(n integer) returns text language plpgsql as $$begin perform set_config('request.jwt.claim.sub',pg_temp.sp_id(n)::text,true);perform public.ai_agent_space_policy_api_v1('catalog','{}');return '00000';exception when others then return SQLSTATE;end$$;
set local role authenticated;
select is(pg_temp.sp_denied(5),'42501','viewer catalog denied');
select is(pg_temp.sp_denied(6),'42501','deleted caller denied');
select is(pg_temp.sp_denied(7),'42501','banned caller denied');
select is(pg_temp.sp_denied(9),'42501','missing profile caller denied');
reset role;
update public.profiles set role='staff' where id=pg_temp.sp_id(1);
select set_config('request.jwt.claim.sub',pg_temp.sp_id(1)::text,true);
set local role authenticated;
select throws_ok($q$select pg_temp.sp_set(2,'0','["space_2","space_1"]',101)$q$,'42501','ai_agent_forbidden','replay rechecks current admin authority');
reset role;
set local role anon;
select throws_ok($q$select public.ai_agent_space_policy_api_v1('catalog','{}')$q$,'42501',null,'anon cannot execute gateway');
reset role;
set local role service_role;
select throws_ok($q$select public.ai_agent_space_policy_api_v1('catalog','{}')$q$,'42501',null,'service cannot impersonate authenticated caller');
reset role;
select ok((select relrowsecurity from pg_class where oid='dashboard_private.ai_agent_space_policy_events'::regclass),'new audit RLS enabled');
select ok(not exists(select 1 from unnest(array['anon','authenticated','service_role'])r cross join unnest(array['chat_user_space_permissions','ai_agent_space_policy_events'])t where has_table_privilege(r,'dashboard_private.'||t,'SELECT,INSERT,UPDATE,DELETE')),'private stores deny all direct access');
select throws_ok($q$update dashboard_private.ai_agent_space_policy_events set after_revision=99$q$,'55000','ai_agent_immutable','audit cannot update');
select throws_ok($q$delete from dashboard_private.ai_agent_space_policy_events$q$,'55000','ai_agent_immutable','audit cannot delete');
select ok(pg_get_functiondef('public.ai_agent_space_policy_api_v1(text,jsonb)'::regprocedure) !~ '40001','final gateway never manually raises40001');
select * from finish();
rollback;
